};
const topicNodeId = String(msg.topic || '').split(';datatype=')[0].trim();
const requestedNodeId = String(msg._nodeId || '').trim();
if (requestedNodeId && requestedNodeId !== topicNodeId) { diagnostics('READ_NODEID_MISMATCH', { batchId: msg._batchId || null, requestedNodeId, topicNodeId }); return null; }
const meta = configured[topicNodeId];
if (!meta || (msg._tag && msg._tag !== meta.tag)) { diagnostics('UNEXPECTED_OPCUA_SAMPLE', { batchId: msg._batchId || null, topicNodeId, tag: msg._tag || null }); return null; }
