const EXPECTED_TAGS = ['sys_man', 'sys_man2', 'sys_sup', 'sys_menu', 'man_step_0', 'man_step_1'];
const STALE_AFTER_MS = 6000;
const samples = flow.get('cpslai2_samples') || {};
